head.script:
// 테스트 설명, 유효성 값 설정
//  · description 은 _1 과 동일 문구 유지
//  · 분리본(_2) 이므로 차이나는 propval(bycolrec / byrowrec) 만 validation 으로 작성
scwin.tData = {
    "description" : "[gridView > P > mergeCellsFixedCols]<br/>Body 의 고정 Column 영역에서 행 또는 컬럼 기준으로 연속적으로 같은 데이터들을 병합하는 방식을 설정합니다.",
    "validation" : [
        "'bycolrec' 설정 시 'bycol' 방식으로 병합 후 'byrow' 방식으로 2차 병합을 수행하며, 'byrow' 방식으로 2차 병합 시 각 Column 의 병합 상태가 같아야 합니다.",
        "'byrowrec' 설정 시 'byrow' 방식으로 병합 후 'bycol' 방식으로 2차 병합을 수행하며, 'bycol' 방식으로 2차 병합 시 각 Row 의 병합 상태가 같아야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  ★ mergeCellsFixedCols 는 생성 attribute 가 아닌 메소드 grid.mergeCellsFixedCols(value) 로 적용한다.
//     (메소드 호출 시 엔진이 fixedCols=true 를 강제 적용하여 고정 Column 영역에만 병합)
//  ★ fixedColumn="2" 로 좌측 2개 컬럼(col1,col2)을 고정 영역에 두고, 그 영역에서 2차 병합이 보이도록 데이터를 설계한다.
//  ★ 미설정('') 이면 메소드를 호출하지 않는다(병합 안함).
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // con_mergeCellsFixedCols : '' 미설정(병합 안함) / 'bycolrec' / 'byrowrec'
    let vMerge = con_mergeCellsFixedCols.getValue();

    // 고정 Column 영역(col1,col2)에서 2차 병합이 드러나도록 설계한 데이터
    //  · 좌상단 2x2 블록(col1,col2 × row0,row1) = 동일값 'A'
    //      → bycolrec : 고정영역에서 bycol 로 col1,col2 각각 세로병합(rowSpan2) 후
    //                   byrow 2차 병합(각 Column 병합 상태 동일 → 가로로 합쳐 rowSpan2+colSpan2 블록)
    //      → byrowrec : 고정영역에서 byrow 로 row0,row1 각각 가로병합(colSpan2) 후
    //                   bycol 2차 병합(각 Row 병합 상태 동일 → 세로로 합쳐 rowSpan2+colSpan2 블록)
    //  · 좌하단 2x2 블록(col1,col2 × row2,row3) = 동일값 'B' → 동일하게 2차 블록병합
    //  · 우측 비고정 컬럼(col3,col4) 은 고정 영역 밖이므로 mergeCellsFixedCols 병합 대상이 아님
    let lblDesc = 'mergeCellsFixedCols=' + (vMerge === '' ? '(미설정)' : vMerge)
        + ' / fixedColumn=2(col1,col2 고정) / 고정영역 2x2 블록 : (col1,col2 × row0,row1)=A, (col1,col2 × row2,row3)=B';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // dataList 생성 (4행) 후 2차 병합 확인용 데이터로 치환
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    let mergeData = [
        { "col1": "A", "col2": "A", "col3": "C", "col4": "C" },
        { "col1": "A", "col2": "A", "col3": "C", "col4": "C" },
        { "col1": "B", "col2": "B", "col3": "D", "col4": "D" },
        { "col1": "B", "col2": "B", "col3": "D", "col4": "D" }
    ];
    dlt_bind.setJSON(mergeData, false);

    let cList = $c.gcm.createCList({ dataList: "data:" + dlt_bind.id, fixedColumn: "2" });

    // target 생성 (mergeCellsFixedCols 속성은 부여하지 않음 → 아래에서 메소드로 적용)
    //  세로 병합 흡수 Row collapse 보정을 위해 defaultCellHeight 와 스크롤 없는 height 사용
    let grp_comp = document.querySelector('.tc_group_basic');
    let ns = $c.gcm.getNameSpace();
    let s = '';
    //  ★ 컬럼 폭 합(480)을 그리드 폭(360)보다 크게 하여 가로 스크롤이 생기도록 함 → col1,col2(좌측 고정)가 스크롤해도 그대로 남는 것을 확인.
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:360px;height:235px;">';
    s += '<w2:caption style="" id="caption1" value="mergeCellsFixedCols 2차 병합 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1(고정)"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2(고정)"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);

    // 생성(데이터 적재 완료) 후 mergeCellsFixedCols() 메소드로 고정영역 병합 적용
    //  미설정('') 이면 호출하지 않음(병합 안함)
    if (vMerge === 'bycolrec' || vMerge === 'byrowrec') {
        let grid = $p.getComponentById("target1");
        grid.mergeCellsFixedCols(vMerge);
    }
}



// 병합 상태 확인 : 고정 Column 영역(col1,col2)의 각 td 에 대해 rowSpan / colSpan 을 읽어
//   1차 병합(한 방향만 span>1) 과 2차 병합(rowSpan>1 AND colSpan>1) 결과를 출력한다.
//  - 2차 병합이 적용되면 하나의 td 가 rowSpan>1 과 colSpan>1 을 동시에 가진다.
scwin.btn_checkMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[옵션] mergeCellsFixedCols : " + (target1.options.mergeCellsFixedCols || "(미설정)") + " / fixedColumn : " + target1.options.fixedColumn);

    // Body 영역 td (데이터 셀만)
    let bodyTds = document.querySelectorAll("td[id*='target1_cell_']");
    if (bodyTds.length === 0) {
        bottom.setReturnValue("Body Cell(td) 을 찾을 수 없습니다.");
        return;
    }

    let recCount = 0;
    let descs = [];
    for (let i = 0; i < bodyTds.length; i++) {
        let td = bodyTds[i];
        // display:none 처리된(병합으로 흡수된) 셀은 제외
        if (getComputedStyle(td).display === "none") continue;

        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        if (rs <= 1 && cs <= 1) continue;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        let r = m ? Number(m[1]) : 0, c = m ? Number(m[2]) : 0;
        let val = (td.textContent || "").trim();
        if (rs > 1 && cs > 1) {
            recCount++;
            descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록(2차)병합(" + rs + "x" + cs + ") = '" + val + "'");
        } else if (rs > 1) {
            descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
        } else {
            descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
        }
    }
    bottom.setReturnValue("병합 그룹 " + descs.length + "개 (2차 블록병합 " + recCount + "개)");
    if (descs.length === 0) bottom.setReturnValue("병합된 셀 없음");
    else for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
}
